window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2ff78d256c835424"]={"versions": [{"id": "FIG-2ff78d256c835424", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Methodology-Aktivitätsdiagramm (SPEM-basiertes Prozessdiagramm) im Kontext der AUTOSAR Classic Platform Methodology zur Modellierung von Software-Komponenten und Datentypen für das Virtual Functional Bus (VFB)-Design.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Rolle</strong>: <code>Software Component Developer</code> (Akteur/SPEM-Role-Definition).\n</li><li><strong>Aktivität</strong>: <code>Define SymbolProps for Types</code> (Prozessschritt/Task).\n</li><li><strong>Artefakte / Work Products</strong>:\n<ul class=\"fig-list\"><li><code>VFB Atomic Software Component</code> (Arbeitsergebnis/Dokumenten-Artefakt).\n</li><li><code>VFB Types</code> (Arbeitsergebnis/Dokumenten-Artefakt).\n</li></ul>\n</li><li><strong>Beziehungen &amp; Schnittstellen</strong>:\n<ul class=\"fig-list\"><li>Gerichtete Assoziation <code>«performs»</code> von <code>Software Component Developer</code> zu <code>Define SymbolProps for Types</code>.\n</li><li>Gerichtete Assoziation <code>«output»</code> von <code>Define SymbolProps for Types</code> zu <code>VFB Atomic Software Component</code> mit Rollenbezeichner <code>+symbolProps</code> und Multiplizität <code>0..*</code>.\n</li><li>Gerichtete Assoziation <code>«output»</code> von <code>Define SymbolProps for Types</code> zu <code>VFB Types</code> mit Rollenbezeichner <code>+symbolProps</code> und Multiplizität <code>0..*</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Akteur <code>Software Component Developer</code> führt die Entwurfsaktivität <code>Define SymbolProps for Types</code> aus (<code>«performs»</code>).\n</li><li>Als Ergebnis dieser Aktivität werden Symbol Properties (<code>+symbolProps</code>) mit einer Kardinalität von jeweils <code>0..*</code> für die Artefakte <code>VFB Atomic Software Component</code> sowie <code>VFB Types</code> definiert bzw. diesen als Modellausgabe (<code>«output»</code>) zugewiesen.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Modellierung von <code>SymbolProps</code> dient der Festlegung symbolspezifischer Eigenschaften (wie C-Code-Identifikatoren oder Präfixen/Namenskonventionen) für Typen und atomare Software-Komponenten im VFB-Kontext. Beide Artefakte können optional mehrere SymbolProps-Definitionen (<code>0..*</code>) erhalten. Die Einhaltung der Namens- und Symboldefinitionen ist für die konsistente Generierung von Rte- und Komponenten-Code sowie Schnittstellenbezeichnern verbindlich.</p>"}, {"id": "FIG-760cfd529bab0fd5", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Methodology-Aktivitätsdiagramm (SPEM-basiertes Prozessdiagramm) im Kontext der AUTOSAR Classic Platform Methodology zur Modellierung von Software-Komponenten und Datentypen für das Virtual Functional Bus (VFB)-Design.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Rolle</strong>: <code>Software Component Developer</code> (Akteur/SPEM-Role-Definition).\n</li><li><strong>Aktivität</strong>: <code>Define SymbolProps for Types</code> (Prozessschritt/Task).\n</li><li><strong>Artefakte / Work Products</strong>:\n<ul class=\"fig-list\"><li><code>VFB Atomic Software Component</code> (Arbeitsergebnis/Dokumenten-Artefakt).\n</li><li><code>VFB Types</code> (Arbeitsergebnis/Dokumenten-Artefakt).\n</li></ul>\n</li><li><strong>Beziehungen &amp; Schnittstellen</strong>:\n<ul class=\"fig-list\"><li>Gerichtete Assoziation <code>«performs»</code> von <code>Software Component Developer</code> zu <code>Define SymbolProps for Types</code>.\n</li><li>Gerichtete Assoziation <code>«output»</code> von <code>Define SymbolProps for Types</code> zu <code>VFB Atomic Software Component</code> mit Rollenbezeichner <code>+symbolProps</code> und Multiplizität <code>0..*</code>.\n</li><li>Gerichtete Assoziation <code>«output»</code> von <code>Define SymbolProps for Types</code> zu <code>VFB Types</code> mit Rollenbezeichner <code>+symbolProps</code> und Multiplizität <code>0..*</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Akteur <code>Software Component Developer</code> führt die Entwurfsaktivität <code>Define SymbolProps for Types</code> aus (<code>«performs»</code>).\n</li><li>Als Ergebnis dieser Aktivität werden Symbol Properties (<code>+symbolProps</code>) mit einer Kardinalität von jeweils <code>0..*</code> für die Artefakte <code>VFB Atomic Software Component</code> sowie <code>VFB Types</code> definiert bzw. diesen als Modellausgabe (<code>«output»</code>) zugewiesen.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Modellierung von <code>SymbolProps</code> dient der Festlegung symbolspezifischer Eigenschaften (wie C-Code-Identifikatoren oder Präfixen/Namenskonventionen) für Typen und atomare Software-Komponenten im VFB-Kontext. Beide Artefakte können optional mehrere SymbolProps-Definitionen (<code>0..*</code>) erhalten. Die Einhaltung der Namens- und Symboldefinitionen ist für die konsistente Generierung von Rte- und Komponenten-Code sowie Schnittstellenbezeichnern verbindlich.</p>"}], "trans": [{"from": "FIG-2ff78d256c835424", "to": "FIG-760cfd529bab0fd5", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
